def convert_author_only_templates(apps, schema_editor):
    """Map the old «only the author» flag onto a named person.

    A row with an author becomes visible to that person. A row with the
    flag and nobody recorded stays shared: there is no one to show it to.
    """
    email_template = apps.get_model("crm", "EmailTemplate")
    for row in email_template.objects.filter(visibility="author").iterator():
        if row.created_by_id:
            row.visibility = "selected"
            row.save(update_fields=["visibility"])
            row.visible_to.add(row.created_by_id)
        else:
            row.visibility = "all"
            row.save(update_fields=["visibility"])


